/* ==========================================================================
   JanSeva AI — Language data and runtime string swapping

   HOW IT WORKS
   Any element carrying data-i18n="some.key" has its text replaced when the
   language changes. Placeholders use data-i18n-placeholder, labels that
   only screen readers hear use data-i18n-label (-> aria-label), and copy
   with embedded links or dynamic slots uses data-i18n-rich + data-i18n-slot.

   Changing the language sets <html lang> so the font stack in tokens.css
   falls through to the right Noto Sans Indic family and screen readers pick
   the matching voice. It also persists across pages via localStorage,
   window.name, and (on file://) query links.
   ========================================================================== */

