    "asst.q1": "स्व-प्रमाणित का क्या मतलब है?",
    "asst.q2": "शपथ पत्र क्या होता है?",
    "asst.q3": "वार्षिक पारिवारिक आय में क्या गिना जाता है?",
    "asst.disclaimer": "सहायक शब्दों का अर्थ समझाता है और सही सेवा बताता है। यह आपके दस्तावेज़ों की जाँच नहीं कर सकता या यह नहीं बता सकता कि आवेदन स्वीकृत होगा या नहीं।",
    "asst.reply.selfAttested.body": "का अर्थ है कि आप अपने दस्तावेज़ की फ़ोटोकॉपी लेकर उस पर स्वयं हस्ताक्षर करते हैं ताकि पुष्टि हो सके कि यह सही प्रति है। इसके लिए नोटरी या राजपत्रित अधिकारी की आवश्यकता नहीं होती।",
    "asst.reply.selfAttested.ex": "अपने आधार कार्ड की फ़ोटोकॉपी करें और प्रति के निचले हिस्से पर हस्ताक्षर करें।",
    "asst.reply.affidavit.body": "एक लिखित बयान है जिसे आप सत्य घोषित करते हुए किसी अधिकृत अधिकारी के सामने हस्ताक्षरित करते हैं। इसका उपयोग तब होता है जब किसी बात को साबित करने के लिए दस्तावेज़ न हो।",
    "asst.reply.affidavit.ex": "यदि दो दस्तावेज़ों में आपका नाम अलग-अलग वर्तनी में लिखा है, तो शपथ पत्र बताता है कि कौन-सा सही है।",
    "asst.reply.domicile.body": "एक दस्तावेज़ है जो प्रमाणित करता है कि आप किसी विशेष राज्य या क्षेत्र के स्थायी निवासी हैं।",
    "asst.reply.domicile.ex": "यह अक्सर राज्य सरकार की योजनाओं और राज्य कोटा कॉलेज प्रवेश के लिए आवश्यक होता है।",
    "asst.reply.income.body": "एक वर्ष में आपके पूरे घर के सभी सदस्यों द्वारा मिलकर अर्जित कुल धनराशि है, केवल आपकी अकेले की आय नहीं।",
    "asst.reply.income.ex": "यदि आप ₹2,00,000 कमाते हैं और आपकी माताजी ₹1,00,000 कमाती हैं, तो आपकी वार्षिक पारिवारिक आय ₹3,00,000 है।",
    "asst.reply.beneficiary.body": "वह व्यक्ति है जिसे किसी योजना से धनराशि या लाभ प्राप्त होता है।",
    "asst.reply.beneficiary.ex": "छात्रवृत्ति में, विद्यार्थी लाभार्थी होता है।",
    "asst.fallback.term": "क्षमा करें",
    "asst.fallback.body": "मेरे पास अभी इसका सरल विवरण नहीं है। शब्दावली देखें या फ़ॉर्म पर दिखे किसी शब्द के बारे में पूछें।",

    "glossary.heading": "कानूनी शब्द सरल भाषा में",
