    "home.feature1.title": "বারোটি ভাষা, একটি পোর্টাল",
    "home.feature1.body": "প্রতিটি স্ক্রিন, লেবেল ও ত্রুটি বার্তা ইংরেজি এবং এগারোটি ভারতীয় ভাষায় উপলব্ধ। আপনার পছন্দ প্রতিটি পৃষ্ঠায় মনে রাখা হয়।",
