    "asst.reply.selfAttested.body": "বলতে বোঝায় আপনি আপনার নথির একটি ফটোকপি নিয়ে নিজেই তাতে স্বাক্ষর করেন এটি আসল প্রতিলিপি নিশ্চিত করতে। এর জন্য নোটারি বা গেজেটেড অফিসারের প্রয়োজন নেই।",
    "asst.reply.selfAttested.ex": "আপনার আধার কার্ডের ফটোকপি করুন, তারপর প্রতিলিপির নিচে স্বাক্ষর করুন।",
    "asst.reply.affidavit.body": "হলো একটি লিখিত বিবৃতি যা আপনি সত্য বলে শপথ করে অনুমোদিত কর্মকর্তার সামনে স্বাক্ষর করেন। কোনো বিষয়ে নথি না থাকলে এটি ব্যবহৃত হয়।",
    "asst.reply.affidavit.ex": "দুটি নথিতে আপনার নামের বানান ভিন্ন হলে, কোনটি সঠিক তা হলফনামা ব্যাখ্যা করে।",
    "asst.reply.domicile.body": "হলো এমন একটি নথি যা প্রমাণ করে আপনি নির্দিষ্ট কোনো রাজ্য বা অঞ্চলের স্থায়ী বাসিন্দা।",
    "asst.reply.domicile.ex": "এটি সাধারণত রাজ্য সরকারি প্রকল্প এবং রাজ্য কোটার কলেজ ভর্তির জন্য প্রয়োজন হয়।",
    "asst.reply.income.body": "হলো এক বছরে আপনার পরিবারের সকল সদস্যের সম্মিলিত মোট আয়, কেবল আপনার একার নয়।",
    "asst.reply.income.ex": "আপনি ₹২,০০,০০০ এবং আপনার মা ₹১,০০,০০০ আয় করলে, আপনার বার্ষিক পারিবারিক আয় ₹৩,০০,০০০।",
    "asst.reply.beneficiary.body": "হলেন সেই ব্যক্তি যিনি কোনো প্রকল্পের অর্থ বা সুবিধা পান।",
    "asst.reply.beneficiary.ex": "বৃত্তির ক্ষেত্রে শিক্ষার্থীই সুবিধাভোগী।",
    "asst.fallback.term": "দুঃখিত",
    "asst.fallback.body": "আমার কাছে এখনও এর সহজ ব্যাখ্যা নেই। শব্দকোষ দেখুন, অথবা ফর্মে দেখা কোনো শব্দ সম্পর্কে জিজ্ঞাসা করুন।",

