    "asst.disclaimer": "सहायक शब्दांचे अर्थ सांगतो आणि योग्य सेवेकडे मार्गदर्शन करतो. तो तुमची कागदपत्रे तपासू शकत नाही किंवा अर्ज मंजूर होईल की नाही हे सांगू शकत नाही.",
    "asst.reply.selfAttested.body": "म्हणजे तुम्ही तुमच्या कागदपत्राची झेरॉक्स काढून ती खरी प्रत असल्याची खात्री करण्यासाठी त्यावर स्वतः सही करता. यासाठी नोटरी किंवा राजपत्रित अधिकाऱ्याची गरज नसते.",
    "asst.reply.selfAttested.ex": "तुमच्या आधार कार्डची झेरॉक्स काढा आणि प्रतीच्या तळाशी सही करा.",
    "asst.reply.affidavit.body": "हे एक लेखी विधान आहे जे तुम्ही खरे असल्याची शपथ घेऊन अधिकृत अधिकाऱ्यासमोर सही करता. एखादी गोष्ट सिद्ध करण्यासाठी कागदपत्र नसल्यास हे वापरले जाते.",
    "asst.reply.affidavit.ex": "दोन कागदपत्रांवर तुमच्या नावाचे स्पेलिंग वेगवेगळे असल्यास, कोणते बरोबर आहे हे प्रतिज्ञापत्रातून स्पष्ट होते.",
    "asst.reply.domicile.body": "हे असे कागदपत्र आहे जे सिद्ध करते की तुम्ही विशिष्ट राज्य किंवा प्रदेशात कायमचे राहता.",
    "asst.reply.domicile.ex": "राज्य सरकारी योजना आणि राज्य कोटा महाविद्यालयीन प्रवेशासाठी हे सहसा लागते.",
    "asst.reply.income.body": "म्हणजे फक्त तुमचेच नाही तर तुमच्या घरातील सर्वांनी मिळून एका वर्षात कमावलेले एकूण पैसे.",
