    "asst.reply.selfAttested.ex": "మీ ఆధార్ కార్డు ఫోటోకాపీ తీసుకొని, ఆ ప్రతి దిగువన సంతకం చేయండి.",
    "asst.reply.affidavit.body": "అంటే నిజమని ప్రమాణం చేస్తూ అధికారి ముందు సంతకం చేసిన రాతపూర్వక ప్రకటన. ఏదైనా నిరూపించడానికి పత్రం లేనప్పుడు దీనిని ఉపయోగిస్తారు.",
    "asst.reply.affidavit.ex": "రెండు పత్రాల్లో మీ పేరు స్పెల్లింగ్ వేరుగా ఉంటే, ఏది సరైనదో అఫిడవిట్ వివరిస్తుంది.",
    "asst.reply.domicile.body": "అంటే మీరు ఒక నిర్దిష్ట రాష్ట్రం లేదా ప్రాంతంలో శాశ్వతంగా నివసిస్తున్నారని నిరూపించే పత్రం.",
    "asst.reply.domicile.ex": "రాష్ట్ర ప్రభుత్వ పథకాలు మరియు రాష్ట్ర కోటా కళాశాల ప్రవేశాలకు ఇది తరచుగా అవసరం.",
    "asst.reply.income.body": "అంటే ఒక సంవత్సరంలో మీ ఒక్కరిదే కాకుండా మీ ఇంట్లోని వారందరూ కలిసి సంపాదించిన మొత్తం డబ్బు.",
    "asst.reply.income.ex": "మీరు ₹2,00,000 మరియు మీ తల్లి ₹1,00,000 సంపాదిస్తే, మీ వార్షిక కుటుంబ ఆదాయం ₹3,00,000.",
    "asst.reply.beneficiary.body": "అంటే ఒక పథకం నుండి డబ్బు లేదా ప్రయోజనం పొందే వ్యక్తి.",
    "asst.reply.beneficiary.ex": "ఉపకార వేతనంలో విద్యార్థి లబ్ధిదారుడు.",
    "asst.fallback.term": "క్షమించండి",
    "asst.fallback.body": "దీనికి నా వద్ద ఇంకా సులభమైన వివరణ లేదు. దయచేసి పదకోశం చూడండి లేదా ఫారమ్‌లో కనిపించిన పదం గురించి అడగండి.",

    "glossary.heading": "సులభ చట్టపరమైన పదాలు",
