    "home.feature1.title": "பன்னிரண்டு மொழிகள், ஒரே தளம்",
    "home.feature1.body": "ஒவ்வொரு திரையும், தலைப்பும், பிழைச் செய்தியும் ஆங்கிலத்திலும் பதினொரு இந்திய மொழிகளிலும் கிடைக்கும். உங்கள் தேர்வு எல்லாப் பக்கங்களிலும் நினைவில் வைக்கப்படும்.",
