    "home.feature2.body": "சுய சான்றொப்பம், சத்தியப்பிரமாணம், இருப்பிடச் சான்றிதழ் போன்ற புரியாத சொல்லைத் தட்டி எடுத்துக்காட்டுடன் ஒரு வரியில் பொருளைப் படியுங்கள்.",
    "home.feature3.title": "முழுமையாக முடிக்கக்கூடிய படிவங்கள்",
    "home.feature3.body": "ஒரு நேரத்தில் ஒரு கேள்வி, உங்கள் மொழியில், தொடங்குவதற்கு முன்பே தேவையான ஆவணங்களின் தெளிவான பட்டியலுடன்.",
    "home.langs.heading": "12 மொழிகளில் கிடைக்கிறது",
    "home.langs.cta": "உங்கள் மொழியைத் தேர்ந்தெடுக்கவும்",

    "appbar.hello": "வணக்கம், {name}!",
