    "services.heading": "அரசு சேவைகள்",
    "services.sub": "சேவைகளைப் பார்த்து விண்ணப்பிக்கவும். தொடங்குவதற்கு முன் தேவையான ஆவணங்கள் ஒவ்வொன்றிலும் பட்டியலிடப்பட்டுள்ளன.",
    "services.searchLabel": "சேவையைத் தேடுங்கள்",
    "services.searchPh": "சேவைகளைத் தேடுங்கள்…",
    "services.categories": "வகைகள்",
    "services.cat.all": "அனைத்து சேவைகள்",
    "services.cat.certificates": "சான்றிதழ்கள்",
    "services.cat.schemes": "திட்டங்கள் & சலுகைகள்",
