    "services.cat.others": "மற்றவை",
    "services.countOne": "{n} சேவை",
    "services.countMany": "{n} சேவைகள்",
    "service.income.title": "வருமானச் சான்றிதழ்",
    "service.income.desc": "உங்கள் குடும்பத்தின் ஆண்டு வருமானத்தை உறுதிப்படுத்துகிறது. கல்வி உதவித்தொகை மற்றும் நலத்திட்டங்களுக்கு அவசியம்.",
    "service.caste.title": "சாதிச் சான்றிதழ்",
    "service.caste.desc": "கல்வி மற்றும் வேலைவாய்ப்பில் இடஒதுக்கீடு சலுகைகளுக்காக உங்கள் சாதியை உறுதிப்படுத்துகிறது.",
    "service.birth.title": "பிறப்புச் சான்றிதழ்",
    "service.birth.desc": "பிறப்பைப் பதிவு செய்து பள்ளிச் சேர்க்கை மற்றும் கடவுச்சீட்டுக்கான சான்றிதழைப் பெறுங்கள்.",
    "service.domicile.title": "இருப்பிடச் சான்றிதழ்",
    "service.domicile.desc": "நீங்கள் ஒரு மாநிலத்தில் நிரந்தரமாக வசிக்கிறீர்கள் என்பதை நிரூபிக்கிறது. மாநில ஒதுக்கீட்டு சேர்க்கைக்குத் தேவை.",
    "service.scholarship.title": "மெட்ரிக்-பின் கல்வி உதவித்தொகை",
    "service.scholarship.desc": "குடும்ப வருமானத்தின் அடிப்படையில் 10ஆம் வகுப்புக்குப் பிறகு மாணவர்களுக்கு நிதியுதவி.",
    "service.ration.title": "குடும்ப அட்டை",
    "service.ration.desc": "மானிய விலையில் உணவு தானியங்கள் பெற குடும்ப அட்டைக்கு விண்ணப்பிக்கவும் அல்லது புதுப்பிக்கவும்.",

    "svcDetail.back": "சேவைகளுக்குத் திரும்புக",
    "svcDetail.income.sub": "உங்கள் வருமானச் சான்றிதழை ஆன்லைனில் பெறுங்கள். பொதுவாக 15 வேலை நாட்களில் வழங்கப்படும்.",
    "svcDetail.whatIs": "இது என்ன",
    "svcDetail.income.whatBody": "வருமானச் சான்றிதழ் என்பது உங்கள் ஆண்டு குடும்ப வருமானத்தைத் தெரிவிக்கும் அதிகாரப்பூர்வ ஆவணம் — அதாவது உங்களுடையது மட்டுமல்ல, உங்கள் வீட்டில் உள்ள அனைவரும் ஓராண்டில் சம்பாதிக்கும் மொத்த வருமானம். உதவித்தொகை, கட்டணச் சலுகை மற்றும் நலத்திட்டங்களுக்கு இது அவசியம்.",
    "svcDetail.callout": "{link} என்பதில் என்ன அடங்கும் என்று தெளிவில்லையா? சொற்களஞ்சியம் எடுத்துக்காட்டுடன் விளக்குகிறது.",
    "svcDetail.stepsHead": "விண்ணப்பிக்கும் படிகள்",
    "svcDetail.income.step1": "JanSeva AI இல் உள்நுழைந்து உங்கள் மொழியைத் தேர்ந்தெடுக்கவும்.",
    "svcDetail.income.step2": "விண்ணப்பப் படிவத்தை நிரப்பவும் — நான்கு சிறிய பிரிவுகள்.",
    "svcDetail.income.step3": "வலதுபுறம் உள்ள மூன்று ஆவணங்களைப் பதிவேற்றவும்.",
    "svcDetail.income.step4": "சமர்ப்பித்து, உங்கள் டாஷ்போர்டிலிருந்து நிலையைக் கண்காணிக்கவும்.",
    "svcDetail.needHead": "தேவையானவை",
    "svcDetail.req.aadhaar": "ஆதார் அட்டை",
    "svcDetail.req.aadhaarHint": "இரு பக்கங்களின் தெளிவான புகைப்படம் அல்லது ஸ்கேன்.",
    "svcDetail.req.income": "வருமானச் சான்று",
    "svcDetail.req.incomeHint": "சம்பளச் சீட்டு அல்லது இருந்தால் படிவம் 16.",
    "svcDetail.req.photo": "சமீபத்திய புகைப்படம்",
    "svcDetail.req.photoHint": "பாஸ்போர்ட் அளவு, கடந்த ஆறு மாதங்களுக்குள் எடுத்தது.",
    "svcDetail.startApp": "விண்ணப்பத்தைத் தொடங்கு",
    "svcDetail.timeHint": "சுமார் 10 நிமிடங்கள் ஆகும். நீங்கள் நிரப்பும்போதே பதில்கள் சேமிக்கப்படும்.",

