    "asst.sub": "சேவை, படிவப் புலம் அல்லது புரியாத சொல் குறித்துக் கேளுங்கள் — ஆங்கிலம், தமிழ், இந்தி அல்லது பன்னிரண்டு மொழிகளில் எதிலும்.",
    "asst.convHeading": "உரையாடல்",
    "asst.convAria": "உதவியாளருடன் உரையாடல்",
    "asst.demoUser": "சுய சான்றொப்பமிட்ட ஆவணம் என்றால் என்ன?",
    "asst.inputLabel": "கேள்வி கேளுங்கள்",
    "asst.inputPh": "உங்கள் மொழியில் கேள்வி கேளுங்கள்…",
    "asst.sendAria": "கேள்வியை அனுப்பு",
    "asst.suggestedHeading": "பரிந்துரைக்கப்பட்ட கேள்விகள்",
    "asst.q1": "சுய சான்றொப்பம் என்றால் என்ன?",
    "asst.q2": "சத்தியப்பிரமாணம் என்றால் என்ன?",
    "asst.q3": "ஆண்டு குடும்ப வருமானத்தில் எவை சேரும்?",
    "asst.disclaimer": "உதவியாளர் சொற்களை விளக்கி சரியான சேவையைச் சுட்டிக்காட்டுவார். உங்கள் ஆவணங்களைச் சரிபார்க்கவோ விண்ணப்பம் ஏற்கப்படுமா என்று கூறவோ முடியாது.",
    "asst.reply.selfAttested.body": "என்பது உங்கள் ஆவணத்தின் நகலை எடுத்து, அது உண்மையான நகல் என்பதை உறுதிப்படுத்த நீங்களே கையொப்பமிடுவதாகும். இதற்கு நோட்டரி அல்லது அரசிதழ் அதிகாரி தேவையில்லை.",
    "asst.reply.selfAttested.ex": "உங்கள் ஆதார் அட்டையை நகலெடுத்து, அந்த நகலின் கீழ்ப்பகுதியில் கையொப்பமிடுங்கள்.",
    "asst.reply.affidavit.body": "என்பது உண்மை என உறுதியளித்து அதிகாரப்பூர்வ அதிகாரியின் முன் கையொப்பமிடும் எழுத்துப்பூர்வ வாக்குமூலம். ஒன்றை நிரூபிக்க ஆவணம் இல்லாதபோது இது பயன்படும்.",
    "asst.reply.affidavit.ex": "இரண்டு ஆவணங்களில் உங்கள் பெயரின் எழுத்துக்கூட்டல் வேறுபட்டால், எது சரி என்பதை சத்தியப்பிரமாணம் விளக்கும்.",
    "asst.reply.domicile.body": "என்பது நீங்கள் ஒரு குறிப்பிட்ட மாநிலம் அல்லது பகுதியில் நிரந்தரமாக வசிக்கிறீர்கள் என்பதை நிரூபிக்கும் ஆவணம்.",
    "asst.reply.domicile.ex": "மாநில அரசுத் திட்டங்கள் மற்றும் மாநில ஒதுக்கீட்டுக் கல்லூரி சேர்க்கைக்கு இது பெரும்பாலும் தேவைப்படும்.",
    "asst.reply.income.body": "என்பது உங்களது மட்டுமல்லாமல், உங்கள் வீட்டில் உள்ள அனைவரும் சேர்ந்து ஓராண்டில் ஈட்டிய மொத்த வருமானமாகும்.",
    "asst.reply.income.ex": "நீங்கள் ₹2,00,000 மற்றும் உங்கள் தாயார் ₹1,00,000 சம்பாதித்தால், உங்கள் ஆண்டு குடும்ப வருமானம் ₹3,00,000.",
    "asst.reply.beneficiary.body": "என்பவர் ஒரு திட்டத்திலிருந்து பணம் அல்லது சலுகையைப் பெறும் நபர்.",
    "asst.reply.beneficiary.ex": "கல்வி உதவித்தொகையில் மாணவர் பயனாளி ஆவார்.",
    "asst.fallback.term": "மன்னிக்கவும்",
    "asst.fallback.body": "இதற்கான எளிய விளக்கம் என்னிடம் இன்னும் இல்லை. சொற்களஞ்சியத்தைப் பார்க்கவும் அல்லது படிவத்தில் உள்ள ஒரு சொல்லைப் பற்றிக் கேளுங்கள்.",

    "glossary.heading": "எளிய சட்டச் சொற்கள்",
    "glossary.sub": "அரசுப் படிவங்களில் அன்றாட வாழ்வில் காணாத சொற்கள் இடம்பெறும். பொதுவான சொற்களின் உண்மையான பொருள் இங்கே.",
    "glossary.searchLabel": "சொல்லைத் தேடுங்கள்",
    "glossary.searchPh": "சொல்லைத் தேடுங்கள்…",
