    "glossary.t1.term": "இருப்பிடச் சான்றிதழ்",
    "glossary.t1.def": "நீங்கள் ஒரு குறிப்பிட்ட மாநிலம் அல்லது பகுதியில் நிரந்தரமாக வசிக்கிறீர்கள் என்பதை நிரூபிக்கும் ஆவணம்.",
    "glossary.t1.ex": "மாநில அரசுத் திட்டங்கள் மற்றும் மாநில ஒதுக்கீட்டுக் கல்லூரி சேர்க்கைக்கு இது பெரும்பாலும் தேவை.",
    "glossary.t2.term": "சத்தியப்பிரமாணம்",
    "glossary.t2.def": "உண்மை என உறுதியளித்து அதிகாரியின் முன் கையொப்பமிடும் எழுத்துப்பூர்வ வாக்குமூலம். ஆவணம் இல்லாதபோது பயன்படும்.",
    "glossary.t2.ex": "இரண்டு ஆவணங்களில் பெயர் வேறுபட்டால் எது சரி என்பதை இது விளக்கும்.",
    "glossary.t3.term": "சுய சான்றொப்பம்",
    "glossary.t3.def": "உண்மையான நகல் என்பதை உறுதிப்படுத்த நீங்களே கையொப்பமிடும் உங்கள் ஆவணத்தின் நகல். நோட்டரி அல்லது அதிகாரி தேவையில்லை.",
    "glossary.t3.ex": "ஆதார் அட்டையை நகலெடுத்து அதன் கீழே கையொப்பமிடுங்கள்.",
    "glossary.t4.term": "ஆண்டு குடும்ப வருமானம்",
    "glossary.t4.def": "உங்களது மட்டுமல்லாமல் உங்கள் வீட்டில் உள்ள அனைவரும் ஓராண்டில் சம்பாதிக்கும் மொத்த பணம்.",
    "glossary.t4.ex": "நீங்கள் ₹2,00,000 மற்றும் உங்கள் தாயார் ₹1,00,000 சம்பாதித்தால், மொத்த வருமானம் ₹3,00,000.",
    "glossary.t5.term": "பயனாளி",
    "glossary.t5.def": "ஒரு திட்டத்திலிருந்து பணம் அல்லது சலுகையைப் பெறும் நபர்.",
    "glossary.t5.ex": "கல்வி உதவித்தொகையில் மாணவர் பயனாளி ஆவார்.",
    "glossary.t6.term": "அரசிதழ் அதிகாரி",
