    "svcDetail.back": "સેવાઓ પર પાછા જાઓ",
    "svcDetail.income.sub": "તમારું આવકનું પ્રમાણપત્ર ઓનલાઇન મેળવો. સામાન્ય રીતે ૧૫ કામકાજના દિવસોમાં જારી થાય છે.",
    "svcDetail.whatIs": "આ શું છે",
    "svcDetail.income.whatBody": "આવકનું પ્રમાણપત્ર એક સત્તાવાર દસ્તાવેજ છે જેમાં તમારી વાર્ષિક કૌટુંબિક આવક દર્શાવાય છે — એટલે કે ફક્ત તમારી જ નહીં, તમારા ઘરમાં રહેતા બધા સભ્યોની એક વર્ષની કુલ કમાણી. શિષ્યવૃત્તિ, ફી માફી અને કલ્યાણ યોજનાઓ માટે આ જરૂરી હોય છે.",
