    "asst.disclaimer": "સહાયક શબ્દો સમજાવે છે અને સાચી સેવા બતાવે છે. તે તમારા દસ્તાવેજો તપાસી શકતો નથી કે અરજી મંજૂર થશે કે નહીં તે કહી શકતો નથી.",
    "asst.reply.selfAttested.body": "નો અર્થ છે કે તમે તમારા દસ્તાવેજની ફોટોકોપી લઈને તે સાચી નકલ છે તેની ખાતરી કરવા જાતે સહી કરો છો. આ માટે નોટરી કે ગેઝેટેડ અધિકારીની જરૂર નથી.",
    "asst.reply.selfAttested.ex": "તમારા આધાર કાર્ડની ફોટોકોપી કરો અને નકલના નીચેના ભાગમાં સહી કરો.",
    "asst.reply.affidavit.body": "એક લેખિત નિવેદન છે જે તમે સાચું હોવાની સોગંદ ખાઈને અધિકૃત અધિકારી સામે સહી કરો છો. કોઈ બાબત સાબિત કરવા દસ્તાવેજ ન હોય ત્યારે તે વપરાય છે.",
    "asst.reply.affidavit.ex": "જો બે દસ્તાવેજોમાં તમારા નામની જોડણી અલગ હોય, તો કઈ સાચી છે તે સોગંદનામું સમજાવે છે.",
    "asst.reply.domicile.body": "એક દસ્તાવેજ છે જે સાબિત કરે છે કે તમે કોઈ ચોક્કસ રાજ્ય કે વિસ્તારમાં કાયમી વસવાટ કરો છો.",
    "asst.reply.domicile.ex": "રાજ્ય સરકારની યોજનાઓ અને રાજ્ય ક્વોટા કોલેજ પ્રવેશ માટે તે ઘણીવાર જરૂરી હોય છે.",
    "asst.reply.income.body": "એટલે ફક્ત તમારી જ નહીં, પરંતુ તમારા ઘરના તમામ સભ્યોની મળીને એક વર્ષમાં થયેલી કુલ કમાણી.",
    "asst.reply.income.ex": "જો તમે ₹૨,૦૦,૦૦૦ અને તમારી માતા ₹૧,૦૦,૦૦૦ કમાય છે, તો તમારી વાર્ષિક કૌટુંબિક આવક ₹૩,૦૦,૦૦૦ છે.",
    "asst.reply.beneficiary.body": "એ વ્યક્તિ છે જેને કોઈ યોજનામાંથી પૈસા કે લાભ મળે છે.",
    "asst.reply.beneficiary.ex": "શિષ્યવૃત્તિમાં વિદ્યાર્થી લાભાર્થી હોય છે.",
    "asst.fallback.term": "માફ કરશો",
    "asst.fallback.body": "મારી પાસે હજી આની સરળ સમજૂતી નથી. શબ્દકોશ જુઓ અથવા ફોર્મમાં દેખાયેલા શબ્દ વિશે પૂછો.",

