    "glossary.t1.ex": "રાજ્ય સરકારની યોજનાઓ અને રાજ્ય ક્વોટા કોલેજ પ્રવેશ માટે તે ઘણીવાર જરૂરી હોય છે.",
    "glossary.t2.term": "સોગંદનામું",
    "glossary.t2.def": "અધિકૃત અધિકારી સામે સહી કરીને સાચું હોવાની સોગંદ સાથેનું લેખિત નિવેદન. પુરાવા માટે દસ્તાવેજ ન હોય ત્યારે વપરાય છે.",
    "glossary.t2.ex": "બે દસ્તાવેજોમાં નામ અલગ હોય તો કયું સાચું છે તે સોગંદનામું જણાવે છે.",
    "glossary.t3.term": "સ્વ-પ્રમાણિત",
    "glossary.t3.def": "તમારા પોતાના દસ્તાવેજની ફોટોકોપી જેના પર તમે જાતે સહી કરીને તે સાચી નકલ હોવાની પુષ્ટિ કરો છો. નોટરી કે અધિકારીની જરૂર નથી.",
    "glossary.t3.ex": "આધાર કાર્ડની ફોટોકોપી કરીને નીચે સહી કરો.",
    "glossary.t4.term": "વાર્ષિક કૌટુંબિક આવક",
    "glossary.t4.def": "એક વર્ષમાં તમારા ઘરના તમામ સભ્યોની મળીને થયેલી કુલ કમાણી, ફક્ત તમારી નહીં.",
    "glossary.t4.ex": "તમે ₹૨,૦૦,૦૦૦ અને તમારી માતા ₹૧,૦૦,૦૦૦ કમાય તો વાર્ષિક કૌટુંબિક આવક ₹૩,૦૦,૦૦૦ છે.",
    "glossary.t5.term": "લાભાર્થી",
