    "asst.sub": "ਕਿਸੇ ਸੇਵਾ, ਫਾਰਮ ਦੇ ਖਾਨੇ ਜਾਂ ਅਣਜਾਣ ਸ਼ਬਦ ਬਾਰੇ ਪੁੱਛੋ — ਅੰਗਰੇਜ਼ੀ, ਪੰਜਾਬੀ, ਹਿੰਦੀ ਜਾਂ ਬਾਰਾਂ ਵਿੱਚੋਂ ਕਿਸੇ ਵੀ ਭਾਸ਼ਾ ਵਿੱਚ।",
    "asst.convHeading": "ਗੱਲਬਾਤ",
    "asst.convAria": "ਸਹਾਇਕ ਨਾਲ ਗੱਲਬਾਤ",
    "asst.demoUser": "ਸਵੈ-ਤਸਦੀਕਸ਼ੁਦਾ ਦਸਤਾਵੇਜ਼ ਦਾ ਕੀ ਮਤਲਬ ਹੈ?",
    "asst.inputLabel": "ਸਵਾਲ ਪੁੱਛੋ",
    "asst.inputPh": "ਆਪਣੀ ਭਾਸ਼ਾ ਵਿੱਚ ਸਵਾਲ ਪੁੱਛੋ…",
    "asst.sendAria": "ਸਵਾਲ ਭੇਜੋ",
    "asst.suggestedHeading": "ਸੁਝਾਏ ਗਏ ਸਵਾਲ",
    "asst.q1": "ਸਵੈ-ਤਸਦੀਕਸ਼ੁਦਾ ਦਾ ਕੀ ਮਤਲਬ ਹੈ?",
    "asst.q2": "ਹਲਫ਼ਨਾਮਾ ਕੀ ਹੁੰਦਾ ਹੈ?",
    "asst.q3": "ਸਾਲਾਨਾ ਪਰਿਵਾਰਕ ਆਮਦਨ ਵਿੱਚ ਕੀ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ?",
    "asst.disclaimer": "ਸਹਾਇਕ ਸ਼ਬਦਾਂ ਦਾ ਮਤਲਬ ਸਮਝਾਉਂਦਾ ਹੈ ਅਤੇ ਸਹੀ ਸੇਵਾ ਦੱਸਦਾ ਹੈ। ਇਹ ਤੁਹਾਡੇ ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਜਾਂਚ ਨਹੀਂ ਕਰ ਸਕਦਾ ਜਾਂ ਇਹ ਨਹੀਂ ਦੱਸ ਸਕਦਾ ਕਿ ਅਰਜ਼ੀ ਮਨਜ਼ੂਰ ਹੋਵੇਗੀ ਜਾਂ ਨਹੀਂ।",
    "asst.reply.selfAttested.body": "ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਤੁਸੀਂ ਆਪਣੇ ਦਸਤਾਵੇਜ਼ ਦੀ ਫੋਟੋਕਾਪੀ ਲੈ ਕੇ ਖੁਦ ਦਸਤਖ਼ਤ ਕਰਦੇ ਹੋ ਤਾਂ ਜੋ ਪੁਸ਼ਟੀ ਹੋਵੇ ਕਿ ਇਹ ਅਸਲ ਕਾਪੀ ਹੈ। ਇਸ ਲਈ ਨੋਟਰੀ ਜਾਂ ਗਜ਼ਟਿਡ ਅਧਿਕਾਰੀ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ।",
    "asst.reply.selfAttested.ex": "ਆਪਣੇ ਆਧਾਰ ਕਾਰਡ ਦੀ ਫੋਟੋਕਾਪੀ ਕਰੋ ਅਤੇ ਕਾਪੀ ਦੇ ਹੇਠਾਂ ਦਸਤਖ਼ਤ ਕਰੋ।",
    "asst.reply.affidavit.body": "ਇੱਕ ਲਿਖਤੀ ਬਿਆਨ ਹੈ ਜਿਸ ਨੂੰ ਤੁਸੀਂ ਸੱਚ ਹੋਣ ਦੀ ਸਹੁੰ ਖਾ ਕੇ ਅਧਿਕਾਰਤ ਅਫ਼ਸਰ ਦੇ ਸਾਹਮਣੇ ਦਸਤਖ਼ਤ ਕਰਦੇ ਹੋ। ਇਹ ਉਦੋਂ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ ਜਦੋਂ ਕਿਸੇ ਗੱਲ ਨੂੰ ਸਾਬਤ ਕਰਨ ਲਈ ਦਸਤਾਵੇਜ਼ ਨਾ ਹੋਵੇ।",
    "asst.reply.affidavit.ex": "ਜੇ ਦੋ ਦਸਤਾਵੇਜ਼ਾਂ ਵਿੱਚ ਤੁਹਾਡੇ ਨਾਮ ਦੇ ਸਪੈਲਿੰਗ ਵੱਖਰੇ ਹਨ, ਤਾਂ ਹਲਫ਼ਨਾਮਾ ਦੱਸਦਾ ਹੈ ਕਿ ਕਿਹੜਾ ਸਹੀ ਹੈ।",
    "asst.reply.domicile.body": "ਇੱਕ ਦਸਤਾਵੇਜ਼ ਹੈ ਜੋ ਸਾਬਤ ਕਰਦਾ ਹੈ ਕਿ ਤੁਸੀਂ ਕਿਸੇ ਖਾਸ ਰਾਜ ਜਾਂ ਖੇਤਰ ਵਿੱਚ ਪੱਕੇ ਤੌਰ ਤੇ ਰਹਿੰਦੇ ਹੋ।",
    "asst.reply.domicile.ex": "ਇਹ ਅਕਸਰ ਰਾਜ ਸਰਕਾਰ ਦੀਆਂ ਸਕੀਮਾਂ ਅਤੇ ਰਾਜ ਕੋਟਾ ਕਾਲਜ ਦਾਖਲਿਆਂ ਲਈ ਲੋੜੀਂਦਾ ਹੁੰਦਾ ਹੈ।",
    "asst.reply.income.body": "ਇੱਕ ਸਾਲ ਵਿੱਚ ਤੁਹਾਡੇ ਘਰ ਦੇ ਸਾਰੇ ਮੈਂਬਰਾਂ ਵੱਲੋਂ ਮਿਲ ਕੇ ਕਮਾਇਆ ਗਿਆ ਕੁੱਲ ਪੈਸਾ ਹੈ, ਸਿਰਫ਼ ਤੁਹਾਡੀ ਕਮਾਈ ਨਹੀਂ।",
    "asst.reply.income.ex": "ਜੇ ਤੁਸੀਂ ₹2,00,000 ਕਮਾਉਂਦੇ ਹੋ ਅਤੇ ਤੁਹਾਡੇ ਮਾਤਾ ਜੀ ₹1,00,000 ਕਮਾਉਂਦੇ ਹਨ, ਤਾਂ ਤੁਹਾਡੀ ਸਾਲਾਨਾ ਪਰਿਵਾਰਕ ਆਮਦਨ ₹3,00,000 ਹੈ।",
    "asst.reply.beneficiary.body": "ਉਹ ਵਿਅਕਤੀ ਹੈ ਜਿਸਨੂੰ ਕਿਸੇ ਸਕੀਮ ਤੋਂ ਪੈਸੇ ਜਾਂ ਲਾਭ ਮਿਲਦਾ ਹੈ।",
    "asst.reply.beneficiary.ex": "ਵਜ਼ੀਫ਼ੇ ਵਿੱਚ ਵਿਦਿਆਰਥੀ ਲਾਭਪਾਤਰੀ ਹੁੰਦਾ ਹੈ।",
    "asst.fallback.term": "ਮਾਫ਼ ਕਰਨਾ",
    "asst.fallback.body": "ਮੇਰੇ ਕੋਲ ਅਜੇ ਇਸਦਾ ਸੌਖਾ ਵਿਵਰਣ ਨਹੀਂ ਹੈ। ਸ਼ਬਦਕੋਸ਼ ਵੇਖੋ ਜਾਂ ਫਾਰਮ ਤੇ ਦਿਖੇ ਕਿਸੇ ਸ਼ਬਦ ਬਾਰੇ ਪੁੱਛੋ।",

    "glossary.heading": "ਆਸਾਨ ਕਾਨੂੰਨੀ ਸ਼ਬਦ",
    "glossary.sub": "ਸਰਕਾਰੀ ਫਾਰਮਾਂ ਵਿੱਚ ਅਜਿਹੇ ਸ਼ਬਦ ਹੁੰਦੇ ਹਨ ਜੋ ਆਮ ਜੀਵਨ ਵਿੱਚ ਘੱਟ ਮਿਲਦੇ ਹਨ। ਇੱਥੇ ਆਮ ਸ਼ਬਦਾਂ ਦਾ ਅਸਲ ਮਤਲਬ ਦਿੱਤਾ ਗਿਆ ਹੈ।",
