    "glossary.t1.ex": "ਇਹ ਅਕਸਰ ਰਾਜ ਸਰਕਾਰ ਦੀਆਂ ਸਕੀਮਾਂ ਅਤੇ ਰਾਜ ਕੋਟਾ ਕਾਲਜ ਦਾਖਲਿਆਂ ਲਈ ਲੋੜੀਂਦਾ ਹੁੰਦਾ ਹੈ।",
    "glossary.t2.term": "ਹਲਫ਼ਨਾਮਾ",
    "glossary.t2.def": "ਅਧਿਕਾਰਤ ਅਫ਼ਸਰ ਸਾਹਮਣੇ ਦਸਤਖ਼ਤ ਕੀਤਾ ਅਤੇ ਸੱਚ ਹੋਣ ਦੀ ਸਹੁੰ ਵਾਲਾ ਲਿਖਤੀ ਬਿਆਨ। ਦਸਤਾਵੇਜ਼ ਨਾ ਹੋਣ ਤੇ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ।",
    "glossary.t2.ex": "ਜੇ ਦੋ ਦਸਤਾਵੇਜ਼ਾਂ ਵਿੱਚ ਨਾਮ ਵੱਖਰਾ ਹੈ, ਤਾਂ ਹਲਫ਼ਨਾਮਾ ਦੱਸਦਾ ਹੈ ਕਿ ਕਿਹੜਾ ਸਹੀ ਹੈ।",
    "glossary.t3.term": "ਸਵੈ-ਤਸਦੀਕਸ਼ੁਦਾ",
    "glossary.t3.def": "ਤੁਹਾਡੇ ਆਪਣੇ ਦਸਤਾਵੇਜ਼ ਦੀ ਫੋਟੋਕਾਪੀ ਜਿਸ ਤੇ ਤੁਸੀਂ ਖੁਦ ਦਸਤਖ਼ਤ ਕਰਕੇ ਪੁਸ਼ਟੀ ਕਰਦੇ ਹੋ ਕਿ ਇਹ ਸਹੀ ਕਾਪੀ ਹੈ। ਨੋਟਰੀ ਜਾਂ ਗਜ਼ਟਿਡ ਅਫ਼ਸਰ ਦੀ ਲੋੜ ਨਹੀਂ।",
    "glossary.t3.ex": "ਆਧਾਰ ਕਾਰਡ ਦੀ ਫੋਟੋਕਾਪੀ ਕਰਕੇ ਹੇਠਾਂ ਦਸਤਖ਼ਤ ਕਰੋ।",
