    "glossary.t5.term": "ਲਾਭਪਾਤਰੀ",
    "glossary.t5.def": "ਉਹ ਵਿਅਕਤੀ ਜਿਸਨੂੰ ਕਿਸੇ ਸਕੀਮ ਤੋਂ ਪੈਸੇ ਜਾਂ ਲਾਭ ਮਿਲਦਾ ਹੈ।",
    "glossary.t5.ex": "ਵਜ਼ੀਫ਼ੇ ਵਿੱਚ ਵਿਦਿਆਰਥੀ ਲਾਭਪਾਤਰੀ ਹੁੰਦਾ ਹੈ।",
