    "home.hero.lede": "ବାରଟି ଭାରତୀୟ ଭାଷା। ସରଳ ଶବ୍ଦରେ ଆଇନଗତ ଅର୍ଥ। ଏପରି ଫର୍ମ ଯାହା ଆପଣ ସହଜରେ ପୂରଣ କରିପାରିବେ।",
    "home.hero.ask": "ସହାୟକଙ୍କୁ ପଚାରନ୍ତୁ",
    "home.features.heading": "JanSeva AI କ’ଣ କରେ",
    "home.features.sub": "ତିନୋଟି ବିଷୟ ଯାହା ନିଷ୍ପତ୍ତି କରେ ଜଣେ ନାଗରିକ ଆବେଦନ ସମ୍ପୂର୍ଣ୍ଣ କରିବେ କି ମଝିରେ ଛାଡ଼ିଦେବେ।",
    "home.feature1.title": "ବାରଟି ଭାଷା, ଗୋଟିଏ ପୋର୍ଟାଲ୍",
    "home.feature1.body": "ପ୍ରତ୍ୟେକ ସ୍କ୍ରିନ୍, ଲେବଲ୍ ଏବଂ ତ୍ରୁଟି ବାର୍ତ୍ତା ଇଂରାଜୀ ଏବଂ ଏଗାରଟି ଭାରତୀୟ ଭାଷାରେ ଉପଲବ୍ଧ। ଆପଣଙ୍କ ପସନ୍ଦ ପ୍ରତ୍ୟେକ ପୃଷ୍ଠାରେ ମନେ ରଖାଯାଏ।",
    "home.feature2.title": "ସରଳ କଥାରେ ଆଇନ ଶବ୍ଦ",
    "home.feature2.body": "ସ୍ୱ-ପ୍ରମାଣିତ, ଶପଥପତ୍ର ବା ବାସିନ୍ଦା ପ୍ରମାଣପତ୍ର ପରି ଅଜଣା ଶବ୍ଦରେ ଟ୍ୟାପ୍ କରି ଉଦାହରଣ ସହିତ ଗୋଟିଏ ବାକ୍ୟରେ ଅର୍ଥ ପଢ଼ନ୍ତୁ।",
    "home.feature3.title": "ପୂରଣ କରିହେବା ଫର୍ମ",
    "home.feature3.body": "ଥରକେ ଗୋଟିଏ ପ୍ରଶ୍ନ, ଆପଣଙ୍କ ଭାଷାରେ, ଆରମ୍ଭ କରିବା ପୂର୍ବରୁ ଆବଶ୍ୟକ ଦଲିଲର ସ୍ପଷ୍ଟ ତାଲିକା ସହିତ।",
