    "svcDetail.back": "ସେବାକୁ ଫେରନ୍ତୁ",
    "svcDetail.income.sub": "ଅନଲାଇନ୍‌ରେ ଆପଣଙ୍କ ଆୟ ପ୍ରମାଣପତ୍ର ପାଆନ୍ତୁ। ସାଧାରଣତଃ ୧୫ କାର୍ଯ୍ୟଦିବସ ମଧ୍ୟରେ ପ୍ରଦାନ କରାଯାଏ।",
    "svcDetail.whatIs": "ଏହା କ’ଣ",
    "svcDetail.income.whatBody": "ଆୟ ପ୍ରମାଣପତ୍ର ହେଉଛି ଏକ ସରକାରୀ ଦଲିଲ ଯାହା ଆପଣଙ୍କ ବାର୍ଷିକ ପାରିବାରିକ ଆୟ ଦର୍ଶାଏ — ଅର୍ଥାତ୍ କେବଳ ଆପଣଙ୍କର ନୁହେଁ, ଆପଣଙ୍କ ଘରର ସମସ୍ତ ସଦସ୍ୟଙ୍କ ଏକ ବର୍ଷର ମୋଟ ରୋଜଗାର। ଛାତ୍ରବୃତ୍ତି, ଫି ଛାଡ଼ ଏବଂ କଲ୍ୟାଣ ଯୋଜନା ପାଇଁ ଏହା ଆବଶ୍ୟକ।",
    "svcDetail.callout": "{link} ରେ କ’ଣ ଅନ୍ତର୍ଭୁକ୍ତ ଜାଣି ନାହାନ୍ତି କି? ଶବ୍ଦକୋଷ ଉଦାହରଣ ସହିତ ବୁଝାଏ।",
    "svcDetail.stepsHead": "ଆବେଦନ କରିବାର ପଦକ୍ଷେପ",
    "svcDetail.income.step1": "JanSeva AI ରେ ସାଇନ୍ ଇନ୍ କରି ଆପଣଙ୍କ ଭାଷା ବାଛନ୍ତୁ।",
    "svcDetail.income.step2": "ଆବେଦନ ଫର୍ମ ପୂରଣ କରନ୍ତୁ — ଚାରୋଟି ଛୋଟ ଭାଗ।",
    "svcDetail.income.step3": "ଡାହାଣ ପଟେ ତାଲିକାଭୁକ୍ତ ତିନୋଟି ଦଲିଲ ଅପଲୋଡ୍ କରନ୍ତୁ।",
