    "asst.sub": "ସେବା, ଫର୍ମ ଘର ବା ଅଜଣା ଶବ୍ଦ ବିଷୟରେ ପଚାରନ୍ତୁ — ଇଂରାଜୀ, ଓଡ଼ିଆ, ହିନ୍ଦୀ ବା ବାରଟି ଭାଷା ମଧ୍ୟରୁ ଯେକୌଣସିରେ।",
    "asst.convHeading": "କଥାବାର୍ତ୍ତା",
    "asst.convAria": "ସହାୟକଙ୍କ ସହିତ କଥାବାର୍ତ୍ତା",
    "asst.demoUser": "ସ୍ୱ-ପ୍ରମାଣିତ ଦଲିଲ ମାନେ କ’ଣ?",
    "asst.inputLabel": "ପ୍ରଶ୍ନ ପଚାରନ୍ତୁ",
    "asst.inputPh": "ଆପଣଙ୍କ ଭାଷାରେ ପ୍ରଶ୍ନ ପଚାରନ୍ତୁ…",
    "asst.sendAria": "ପ୍ରଶ୍ନ ପଠାନ୍ତୁ",
    "asst.suggestedHeading": "ପ୍ରସ୍ତାବିତ ପ୍ରଶ୍ନ",
    "asst.q1": "ସ୍ୱ-ପ୍ରମାଣିତ ମାନେ କ’ଣ?",
    "asst.q2": "ଶପଥପତ୍ର କ’ଣ?",
    "asst.q3": "ବାର୍ଷିକ ପାରିବାରିକ ଆୟରେ କ’ଣ ଗଣାଯାଏ?",
    "asst.disclaimer": "ସହାୟକ ଶବ୍ଦର ଅର୍ଥ ବୁଝାନ୍ତି ଏବଂ ସଠିକ୍ ସେବା ଦେଖାନ୍ତି। ଏହା ଆପଣଙ୍କ ଦଲିଲ ଯାଞ୍ଚ କରିପାରିବ ନାହିଁ କି ଆବେଦନ ମଞ୍ଜୁର ହେବ କି ନାହିଁ କହିପାରିବ ନାହିଁ।",
    "asst.reply.selfAttested.body": "ଅର୍ଥ ହେଉଛି ଆପଣ ନିଜ ଦଲିଲର ଫଟୋକପି ନେଇ ତାହା ସଠିକ୍ ନକଲ ବୋଲି ନିଶ୍ଚିତ କରିବାକୁ ନିଜେ ଦସ୍ତଖତ କରନ୍ତି। ଏଥିପାଇଁ ନୋଟାରୀ ବା ଗେଜେଟେଡ୍ ଅଧିକାରୀଙ୍କ ଆବଶ୍ୟକତା ନାହିଁ।",
    "asst.reply.selfAttested.ex": "ଆପଣଙ୍କ ଆଧାର କାର୍ଡର ଫଟୋକପି କରନ୍ତୁ, ତା’ପରେ ନକଲର ତଳେ ଦସ୍ତଖତ କରନ୍ତୁ।",
    "asst.reply.affidavit.body": "ହେଉଛି ଏକ ଲିଖିତ ବିବୃତ୍ତି ଯାହା ସତ୍ୟ ବୋଲି ଶପଥ ନେଇ ଅଧିକୃତ ଅଧିକାରୀଙ୍କ ଆଗରେ ଦସ୍ତଖତ କରାଯାଏ। କୌଣସି କଥା ପ୍ରମାଣ କରିବାକୁ ଦଲିଲ ନ ଥିଲେ ଏହା ବ୍ୟବହୃତ ହୁଏ।",
    "asst.reply.affidavit.ex": "ଦୁଇଟି ଦଲିଲରେ ଆପଣଙ୍କ ନାମର ବନାନ ଅଲଗା ଥିଲେ, କେଉଁଟି ଠିକ୍ ତାହା ଶପଥପତ୍ର ବୁଝାଏ।",
    "asst.reply.domicile.body": "ହେଉଛି ଏକ ଦଲିଲ ଯାହା ପ୍ରମାଣ କରେ ଆପଣ ଏକ ନିର୍ଦ୍ଦିଷ୍ଟ ରାଜ୍ୟ ବା ଅଞ୍ଚଳର ସ୍ଥାୟୀ ବାସିନ୍ଦା।",
    "asst.reply.domicile.ex": "ରାଜ୍ୟ ସରକାରୀ ଯୋଜନା ଏବଂ ରାଜ୍ୟ କୋଟା କଲେଜ ନାମଲେଖା ପାଇଁ ଏହା ପ୍ରାୟତଃ ଆବଶ୍ୟକ ହୁଏ।",
    "asst.reply.income.body": "ହେଉଛି ଗୋଟିଏ ବର୍ଷରେ କେବଳ ଆପଣଙ୍କର ନୁହେଁ, ଆପଣଙ୍କ ଘରର ସମସ୍ତ ସଦସ୍ୟଙ୍କ ମିଳିତ ମୋଟ ଆୟ।",
    "asst.reply.income.ex": "ଯଦି ଆପଣ ₹୨,୦୦,୦୦୦ ଏବଂ ଆପଣଙ୍କ ମାଆ ₹୧,୦୦,୦୦୦ ରୋଜଗାର କରନ୍ତି, ତେବେ ବାର୍ଷିକ ପାରିବାରିକ ଆୟ ₹୩,୦୦,୦୦୦।",
    "asst.reply.beneficiary.body": "ହେଉଛନ୍ତି ସେହି ବ୍ୟକ୍ତି ଯିଏ କୌଣସି ଯୋଜନାରୁ ଟଙ୍କା ବା ସୁବିଧା ପାଆନ୍ତି।",
    "asst.reply.beneficiary.ex": "ଛାତ୍ରବୃତ୍ତିରେ ଛାତ୍ର ହିଁ ହିତାଧିକାରୀ।",
    "asst.fallback.term": "କ୍ଷମା କରିବେ",
    "asst.fallback.body": "ମୋ ପାଖରେ ଏହାର ସରଳ ବ୍ୟାଖ୍ୟା ଏପର୍ଯ୍ୟନ୍ତ ନାହିଁ। ଶବ୍ଦକୋଷ ଦେଖନ୍ତୁ କିମ୍ବା ଫର୍ମରେ ଥିବା କୌଣସି ଶବ୍ଦ ବିଷୟରେ ପଚାରନ୍ତୁ।",

    "glossary.heading": "ସରଳ ଆଇନ ଶବ୍ଦ",
    "glossary.sub": "ସରକାରୀ ଫର୍ମରେ ଏପରି ଶବ୍ଦ ଥାଏ ଯାହା ସାଧାରଣ ଜୀବନରେ କମ୍ ଦେଖାଯାଏ। ପ୍ରଚଳିତ ଶବ୍ଦଗୁଡ଼ିକର ପ୍ରକୃତ ଅର୍ଥ ଏଠାରେ ଅଛି।",
    "glossary.searchLabel": "ଶବ୍ଦ ଖୋଜନ୍ତୁ",
    "glossary.searchPh": "ଶବ୍ଦ ଖୋଜନ୍ତୁ…",
    "glossary.termsHeading": "ଶବ୍ଦଗୁଡ଼ିକ",
    "glossary.countAll": "{n}ଟି ଶବ୍ଦ",
    "glossary.countOne": "{n}ଟି ଶବ୍ଦ ମିଳିଲା",
    "glossary.countMany": "{n}ଟି ଶବ୍ଦ ମିଳିଲା",
    "glossary.examplePrefix": "ଉଦାହରଣ: ",
    "glossary.askAbout": "ଏ ବିଷୟରେ ସହାୟକଙ୍କୁ ପଚାରନ୍ତୁ",
    "glossary.t1.term": "ବାସିନ୍ଦା ପ୍ରମାଣପତ୍ର",
    "glossary.t1.def": "ଆପଣ ଏକ ନିର୍ଦ୍ଦିଷ୍ଟ ରାଜ୍ୟ ବା ଅଞ୍ଚଳର ସ୍ଥାୟୀ ବାସିନ୍ଦା ବୋଲି ପ୍ରମାଣ କରୁଥିବା ଦଲିଲ।",
    "glossary.t1.ex": "ରାଜ୍ୟ ସରକାରୀ ଯୋଜନା ଏବଂ ରାଜ୍ୟ କୋଟା କଲେଜ ନାମଲେଖା ପାଇଁ ଏହା ପ୍ରାୟତଃ ଆବଶ୍ୟକ ହୁଏ।",
    "glossary.t2.term": "ଶପଥପତ୍ର",
    "glossary.t2.def": "ଅଧିକୃତ ଅଧିକାରୀଙ୍କ ଆଗରେ ଦସ୍ତଖତ କରି ସତ୍ୟ ବୋଲି ଶପଥ ନିଆଯାଇଥିବା ଲିଖିତ ବିବୃତ୍ତି। ଦଲିଲ ନ ଥିଲେ ବ୍ୟବହୃତ ହୁଏ।",
    "glossary.t2.ex": "ଦୁଇଟି ଦଲିଲରେ ନାମ ଅଲଗା ଥିଲେ କେଉଁଟି ଠିକ୍ ତାହା ଶପଥପତ୍ର ବୁଝାଏ।",
    "glossary.t3.term": "ସ୍ୱ-ପ୍ରମାଣିତ",
    "glossary.t3.def": "ଆପଣଙ୍କ ନିଜ ଦଲିଲର ଫଟୋକପି ଯାହା ସତ୍ୟ ନକଲ ବୋଲି ନିଶ୍ଚିତ କରିବାକୁ ଆପଣ ନିଜେ ଦସ୍ତଖତ କରନ୍ତି। ନୋଟାରୀ ବା ଅଧିକାରୀ ଆବଶ୍ୟକ ନାହିଁ।",
    "glossary.t3.ex": "ଆଧାର କାର୍ଡର ଫଟୋକପି କରି ତଳେ ଦସ୍ତଖତ କରନ୍ତୁ।",
    "glossary.t4.term": "ବାର୍ଷିକ ପାରିବାରିକ ଆୟ",
    "glossary.t4.def": "କେବଳ ଆପଣଙ୍କର ନୁହେଁ, ଆପଣଙ୍କ ଘରର ସମସ୍ତ ସଦସ୍ୟଙ୍କ ମିଳିତ ଏକ ବର୍ଷର ମୋଟ ଆୟ।",
    "glossary.t4.ex": "ଆପଣ ₹୨,୦୦,୦୦୦ ଏବଂ ମାଆ ₹୧,୦୦,୦୦୦ ରୋଜଗାର କଲେ ବାର୍ଷିକ ପାରିବାରିକ ଆୟ ₹୩,୦୦,୦୦୦।",
    "glossary.t5.term": "ହିତାଧିକାରୀ",
    "glossary.t5.def": "ଯିଏ କୌଣସି ଯୋଜନାରୁ ଟଙ୍କା ବା ସୁବିଧା ପାଆନ୍ତି।",
    "glossary.t5.ex": "ଛାତ୍ରବୃତ୍ତିରେ ଛାତ୍ର ହିଁ ହିତାଧିକାରୀ।",
    "glossary.t6.term": "ଗେଜେଟେଡ୍ ଅଧିକାରୀ",
    "glossary.t6.def": "ଜଣେ ବରିଷ୍ଠ ସରକାରୀ ଅଧିକାରୀ ଯାହାଙ୍କ ଦସ୍ତଖତ ସରକାରୀ ଯାଞ୍ଚ ଭାବେ ଗ୍ରହଣ କରାଯାଏ।",
    "glossary.t6.ex": "ସରକାରୀ ବିଦ୍ୟାଳୟର ପ୍ରଧାନ ଶିକ୍ଷକ କିମ୍ବା ତହସିଲଦାର ସାଧାରଣତଃ ଦସ୍ତଖତ କରିପାରନ୍ତି।",

