const STORAGE_KEY = "janseva.lang";
const WINDOW_NAME_PREFIX = "janseva.lang:";

function isValidLang(code) {
  return Boolean(code && LANGUAGES.some(function (l) { return l.code === code; }));
}

/* localStorage throws in private-browsing and sandboxed contexts, so every
   access is guarded and paired with a window.name fallback for file:// tabs. */
function readStoredLang() {
  try {
    var stored = window.localStorage.getItem(STORAGE_KEY);
    if (isValidLang(stored)) return stored;
  } catch (err) {
    /* fall through to window.name */
  }
  try {
    if (typeof window.name === "string" && window.name.indexOf(WINDOW_NAME_PREFIX) === 0) {
      var candidate = window.name.slice(WINDOW_NAME_PREFIX.length);
      if (isValidLang(candidate)) return candidate;
    }
  } catch (err) {
    /* ignore */
  }
  return null;
}

function writeStoredLang(code) {
  try {
    window.localStorage.setItem(STORAGE_KEY, code);
  } catch (err) {
    /* ignore — see above */
  }
  try {
    if (!window.name || window.name.indexOf(WINDOW_NAME_PREFIX) === 0) {
      window.name = WINDOW_NAME_PREFIX + code;
    }
  } catch (err) {
    /* ignore */
  }
}

function readQueryLang() {
  try {
    var params = new URLSearchParams(window.location.search);
    var q = params.get("lang");
    return isValidLang(q) ? q : null;
  } catch (err) {
    return null;
  }
}

function getLanguage(code) {
  return LANGUAGES.find(function (l) { return l.code === code; });
}

function translate(key, code) {
  var langCode = isValidLang(code) ? code : currentLanguage();
  var table = STRINGS[langCode] || {};
  return Object.prototype.hasOwnProperty.call(table, key)
    ? table[key]
    : (Object.prototype.hasOwnProperty.call(STRINGS.en, key) ? STRINGS.en[key] : key);
}

function formatMessage(key, code, vars) {
  var text = translate(key, code);
  if (!vars) return text;
  return text.replace(/\{(\w+)\}/g, function (match, name) {
    return Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : match;
  });
}

/* Replace text around preserved [data-i18n-slot] nodes without innerHTML so
   slot references, attributes and listeners stay intact across switches. */
function renderRichElement(el, template) {
  if (!el._i18nSlots) {
    var slots = {};
    el.querySelectorAll("[data-i18n-slot]").forEach(function (node) {
      slots[node.dataset.i18nSlot] = node;
    });
    el._i18nSlots = slots;
  }

  var fragment = document.createDocumentFragment();
  var parts = template.split(/(\{\w+\})/g);
  parts.forEach(function (part) {
    var m = /^\{(\w+)\}$/.exec(part);
    if (m && el._i18nSlots[m[1]]) {
      fragment.appendChild(el._i18nSlots[m[1]]);
    } else if (part) {
      fragment.appendChild(document.createTextNode(part));
    }
  });

  while (el.firstChild) el.removeChild(el.firstChild);
  el.appendChild(fragment);
}

/* When opened via file://, some browsers isolate localStorage per HTML file;
   propagating ?lang= on relative .html links keeps all 9 pages in sync. */
function syncFileLanguageLinks(code) {
  if (window.location.protocol !== "file:") return;
  document.querySelectorAll("a[href]").forEach(function (link) {
    var raw = link.getAttribute("href");
    if (!raw || raw.charAt(0) === "#" || /^[a-z]+:/i.test(raw)) return;
    var hashIdx = raw.indexOf("#");
    var hash = hashIdx !== -1 ? raw.slice(hashIdx) : "";
    var base = hashIdx !== -1 ? raw.slice(0, hashIdx) : raw;
    var qIdx = base.indexOf("?");
    var path = qIdx !== -1 ? base.slice(0, qIdx) : base;
    if (!/\.html$/i.test(path)) return;
    var params = new URLSearchParams(qIdx !== -1 ? base.slice(qIdx + 1) : "");
    params.set("lang", code);
    link.setAttribute("href", path + "?" + params.toString() + hash);
  });
}

function applyLanguage(code) {
  var lang = getLanguage(code);
  if (!lang) return;

  document.documentElement.lang = code;

  document.querySelectorAll("[data-i18n]").forEach(function (el) {
    var text = translate(el.dataset.i18n, code);
    if (el.tagName === "TITLE") {
      document.title = text;
    } else {
      el.textContent = text;
    }
  });

  document.querySelectorAll("[data-i18n-rich]").forEach(function (el) {
    renderRichElement(el, translate(el.dataset.i18nRich, code));
  });

  document.querySelectorAll("[data-i18n-placeholder]").forEach(function (el) {
    el.placeholder = translate(el.dataset.i18nPlaceholder, code);
  });

  document.querySelectorAll("[data-i18n-label]").forEach(function (el) {
    el.setAttribute("aria-label", translate(el.dataset.i18nLabel, code));
  });

  /* The header chip always shows the endonym, never a translated label. */
  document.querySelectorAll("[data-lang-display]").forEach(function (el) {
    el.textContent = lang.native;
  });

  document.querySelectorAll(".lang-tile, .lang-chip").forEach(function (el) {
    el.setAttribute("aria-pressed", String(el.dataset.lang === code));
  });

  document.querySelectorAll(".lang-menu__item").forEach(function (el) {
    el.setAttribute("aria-checked", String(el.dataset.lang === code));
  });

  writeStoredLang(code);
  syncFileLanguageLinks(code);

  try {
    document.dispatchEvent(new CustomEvent("janseva:languagechange", {
      detail: { code: code, lang: lang }
    }));
  } catch (err) {
    /* ignore in environments without CustomEvent */
  }
}

function currentLanguage() {
  var fromQuery = readQueryLang();
  if (fromQuery) {
    writeStoredLang(fromQuery);
    return fromQuery;
  }
  return readStoredLang() || "en";
}
